import {storyGlyph} from './glyphs.js?v=0.31.8';
import {lifestyleStory,lifestyleIncomeRange} from './lifestyle-story.js?v=0.31.0';
import {formatSalary} from './salary-progression.js?v=0.31.0';
import {careers,wageOptions} from './finance-data.js?v=0.31.0';
import {calculateLifestyle,lifestyleSources,austinRentContext} from './lifestyle.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
import {usd} from './finance-ui.js?v=0.31.0';
const cash=n=>usd(Math.round(n));
const more=(body,label='More info')=>`<details class="more-info"><summary>${label}</summary><div>${body}</div></details>`;
const input=(p,k,label,help='',step='1')=>`<div class="field"><label class="label" for="life-${k}">${label}</label><input type="number" id="life-${k}" data-lifestyle="${k}" min="0" step="${step}" value="${h(p[k])}" placeholder="Enter amount">${help?more(`<p>${help}</p>`):''}</div>`;
const select=(p,k,label,options)=>`<div class="field"><label class="label" for="life-${k}">${label}</label><select id="life-${k}" data-lifestyle="${k}">${options.map(([v,l])=>`<option value="${v}" ${p[k]===v?'selected':''}>${h(l)}</option>`).join('')}</select></div>`;
const section=(n,title,content)=>`<details class="life-input-section"><summary><span>${n}</span>${title}<b>+</b></summary><div class="life-section-body">${content}</div></details>`;
export function lifestyleScope(p){const c=careers.find(c=>c.id===p.careerId);return `${c?`${h(c.title)} · ${p.band==='custom'?'Custom income':c.earnings.status==='sourced'?'Austin metro · May 2025':p.band==='dallas'?'Dallas posting estimate':p.band==='houston'?'Houston posting estimate':'Austin posting estimate · small sample'}`:'Custom income illustration'}${p.gross!==''?' · '+usd(Number(p.gross))+' gross / year':''}`;}
export function lifestylePage(state){const p=state.finance.lifestyle,c=careers.find(c=>c.id===p.careerId);return `<div class="page-intro life-intro"><div><span class="eyebrow">AUSTIN, TEXAS · ONE ADULT · NO CHILDREN</span><h1>A salary.<br>A life you can picture.</h1><p class="intro-copy">Start with local pay. Shape the life around it.</p></div><a class="button secondary" href="#/catalog">Explore careers ↗</a></div><section class="life-career-picker">${select(p,'careerId','Choose a career',[['','Custom income illustration'],...careers.map(c=>[c.id,c.title])])}${select(p,'band','Pay level',wageOptions(c))}</section><p class="life-scope" id="life-scope">${lifestyleScope(p)}</p>${c?.earnings.status==='posting_estimate'?'<p class="life-posting-note">Posting estimate · employee tax example. Studio costs need a <a href="#/money/business">business budget →</a></p>':''}<div id="lifestyle-output" class="life-output" aria-live="polite">${lifestyleOutput(p)}</div><details class="life-tuning"><summary>Make this picture yours</summary><section class="life-inputs" aria-label="Lifestyle assumptions">${section('01','Income & take-home pay',`${p.careerId?`<a href="#/career/${p.careerId}">Career pay & Texas requirements ↗</a>`:''}${select(p,'netMode','Take-home pay',[['estimate','Estimate using 2026 tax rules'],['manual','Enter my own monthly take-home']])}${p.netMode==='estimate'?`${input(p,'gross','Gross income / year ($)')}${input(p,'retirement','Pretax retirement (%)','Eligible employee plan, under 50; no employer match.','.1')}${input(p,'health','Health budget / month ($)','Premiums and out-of-pocket spending. Subtracted after tax in this model.')}`:input(p,'manualNet','Take-home / month ($)','Already after taxes, retirement, and health costs.')}${more('<p>The standard wage quartiles describe the employee distribution. They are not starting pay or experience milestones. Tattoo city options are posting averages, not quartiles. Employee wages exclude self-employment and employer benefits. Enter personal take-home for self-employment.</p>')}`)}${section('02','Home & housing',`${select(p,'housingMode','Rent or own',[['rent','Rent'],['own','Explore owning']])}${p.housingMode==='rent'?`<div class="life-preset-buttons"><button data-action="life-rent" data-value="1350" data-utilities="180">1 bedroom alone · $1,530 total</button><button data-action="life-rent" data-value="818.50" data-utilities="90">Share 2 bedrooms · $909 total</button><button data-action="life-rent" data-value="2100" data-utilities="180">Metro rental median · $2,280 total</button></div>${input(p,'rent','Rent / month ($)')}${more(`<p>HUD FY 2027 Austin gross-rent benchmarks: 1 bedroom $1,530; 2 bedrooms $1,817. The first two presets split these into base rent and utility assumptions. Sharing splits the 2-bedroom total equally.</p><p>The third uses the September 2026 metro median closed rent of $2,100 across housing types, plus $180 utilities. It does not specify a house size or neighborhood.</p><a href="${austinRentContext.sourceURL}#page=45" target="_blank" rel="noopener noreferrer">HUD source ↗</a> · <a href="https://www.unlockmls.com/news/september-2026-central-texas-housing-report" target="_blank" rel="noopener noreferrer">Austin housing report ↗</a>`)}`:`<div class="life-two">${input(p,'homePrice','Home price ($)')}${input(p,'downPercent','Down payment (%)')}${input(p,'mortgageRate','Mortgage rate (%)','7.40%: Freddie Mac national 30-year benchmark, October 15, 2026. Personal loan rates differ.','.01')}${input(p,'pmiRate','PMI rate / year (%)','Used below 20% down. 0.6% is a planning estimate, not an insurance quote.','.1')}${input(p,'mortgageYears','Mortgage years')}${input(p,'propertyTax','Property tax / year (%)','2% is an editable planning assumption. A property bill depends on the parcel and exemptions.','.01')}${input(p,'homeInsurance','Home insurance / month ($)')}${input(p,'hoa','HOA / month ($)')}${input(p,'maintenance','Maintenance / year (%)','Reserve assumption, not a prediction.','.1')}${input(p,'cashSaved','Purchase savings ($)')}</div>${more('<p>$421,000 is the September 2026 Austin metro median closed sale price. The model adds 3% closing costs and six months of essential expenses to the down payment. Below 20% down, the model includes PMI at the entered rate. The 0.6% default is a planning midpoint of Freddie Mac’s broad cost guide; actual premiums differ.</p><p><a href="https://www.freddiemac.com/pmms" target="_blank" rel="noopener noreferrer">Freddie Mac rate ↗</a> · <a href="https://www.unlockmls.com/news/september-2026-central-texas-housing-report" target="_blank" rel="noopener noreferrer">Austin housing report ↗</a></p>')}`}${input(p,'utilities','Utilities / month ($)','Avoid counting utilities already included in rent.')}`)}${section('03','Getting around',`${select(p,'carMode','Your transport',[['transit','Transit, bicycle & occasional rides'],['paid','Paid-off car'],['used','Financed used compact'],['new','Financed new car']])}${p.carMode==='transit'?`${input(p,'transit','Transit pass / month ($)','CapMetro local monthly fare: $41.25, October 2026. Fare changes January 10, 2027.','.01')}${input(p,'rides','Other rides / month ($)')}`:`${['used','new'].includes(p.carMode)?`<div class="life-preset-buttons"><button data-action="life-car" data-id="used">Used compact · $22,000</button><button data-action="life-car" data-id="new">New compact · $32,000</button></div><div class="life-two">${input(p,'carPrice','Vehicle price with fees ($)')}${input(p,'carDown','Down payment ($)')}${input(p,'carRate','Loan rate (%)','Q2 2026 national averages: used 11.19%, new 6.35%. Your rate can differ.','.01')}${input(p,'carMonths','Loan months')}</div>`:''}<div class="life-two">${input(p,'fuel','Fuel / month ($)')}${input(p,'carInsurance','Insurance / month ($)')}${input(p,'carMaintenance','Maintenance / month ($)')}${input(p,'carOther','Parking & other / month ($)')}</div>`}${more('<p>Vehicle prices and operating costs are editable scenarios. Loan-rate defaults use Experian Q2 2026 national averages, not Austin quotes. A compact could be a Civic or Corolla; these are type examples, not price quotes. Down payments and future replacement savings are separate. Transit access depends on the actual home, worksite, and shift.</p>')}`)}${section('04','Essentials, debt & saving',`<div class="life-two">${input(p,'groceries','Groceries / month ($)')}${input(p,'phone','Phone & internet / month ($)')}${input(p,'household','Household & personal care ($)','Include renters insurance and irregular essentials.')}${input(p,'debt','Debt payments / month ($)','No student debt is assumed from a degree.')}${input(p,'extraNeeds','Dependent care & other needs ($)')}${input(p,'saving','Cash savings / month ($)','Separate from payroll retirement.')}</div>`)}${section('05','Meals, travel & fun',`<div class="life-two">${input(p,'quickCount','Counter-service meals / month')}${input(p,'quickPrice','All-in price / counter meal ($)')}${input(p,'casualCount','Sit-down meals / month')}${input(p,'casualPrice','All-in price / sit-down meal ($)')}${input(p,'specialCount','Special meals / month')}${input(p,'specialPrice','All-in price / special meal ($)')}${input(p,'travel','Travel fund / month ($)')}${input(p,'tripPrice','All-in budget / trip ($)')}${input(p,'recreation','Recreation / month ($)')}${input(p,'outingPrice','Budget / outing ($)')}${input(p,'clothing','Clothing / month ($)')}${input(p,'itemPrice','Target price / clothing item ($)')}</div>${more('<p>These are editable price baskets, not verified restaurant menus, shopping quotes, or bookable trips. Dining includes tax and tip. Travel includes transport, lodging, meals, and activities. Clothing brands are examples, not income categories.</p>')}`)}${more(`<div class="field"><label class="label" for="life-notes">My notes</label><textarea id="life-notes" data-lifestyle="notes" maxlength="2000">${h(p.notes)}</textarea></div><p>Saved in this browser. Lifestyle details stay out of the general report. This scenario export and full-draft backups include them.</p>`,'Notes & privacy')}<div class="button-group"><button class="button secondary" data-action="life-export">Export scenario</button><button class="text-link" data-action="life-reset">Reset assumptions</button></div></section></details><a class="source-audit-link" href="#/source-review">Sources behind these estimates →</a>${more(`<p>Reviewed October 16, 2026. Wages: May 2025 Austin metro; tattooing uses small 2026 posting samples. College prices: 2026–27. Taxes: 2026. Housing: HUD FY 2027 and September 2026 metro sales. These periods are not inflation-adjusted. This is a present-dollar scenario, not a forecast to graduation.</p><p>Tax model: single nondependent employee under 50; $16,100 standard deduction; ordinary wages; eligible pretax retirement; no credits; full Social Security and Medicare. Texas has no individual wage income tax. Health costs are deducted after tax. Manual take-home replaces these deductions.</p><p>MIT’s Travis County basic-needs budget is a reasonableness reference, not a lifestyle promise. Food, medical, and transport categories have different scopes. Meals, travel, clothing, insurance, tax, and maintenance inputs remain editable assumptions. Benefits, moving costs, rent deposits, vehicle down payments, and surprises need separate consideration. Loan payments are zero until entered; this is not a debt-free prediction. Lifestyle never scores aptitude or ranks careers.</p><div class="source-links">${Object.entries({tax:'IRS tax rules',retirement:'IRS retirement limit',fica:'SSA payroll taxes',medicare:'IRS Medicare tax',housing:'HUD rent benchmarks',buying:'CFPB home costs',local:'Travis County living costs',transit:'CapMetro fares',texas:'Texas tax guidance'}).map(([k,t])=>`<a href="${lifestyleSources[k]}" target="_blank" rel="noopener noreferrer">${t} ↗</a>`).join('')}</div>`,'Sources & calculation details')}`;}
const tile=(symbol,label,title,amount,body,sectionIndex)=>`<article class="life-story"><span class="life-symbol" aria-hidden="true">${storyGlyph(label)}</span><span class="overline">${label}</span><h3>${title}</h3><strong>${amount}</strong>${body?more(body):''}<button class="text-link" data-action="life-adjust" data-id="${sectionIndex}">Adjust →</button></article>`;
export function lifestyleDetailOutput(p){const r=calculateLifestyle(p);if(r.status!=='illustration')return `<section class="life-summary"><span class="overline">YOUR INCOME SCENARIO</span><h2>${p.gross===''?'Austin pay is not published.':'A few amounts are missing.'}</h2><p>${p.gross===''?'Enter an income to see a lifestyle. No salary has been invented.':'Add: '+r.issues.map(h).join(', ')+'.'}</p><button class="button" data-action="life-adjust" data-id="0">Enter my income →</button></section>`;const deficit=r.remaining<0;return `<section class="life-summary ${deficit?'life-deficit':''}"><span class="overline">YOUR MONTHLY PICTURE</span><h2>${deficit?'This plan spends more than it earns.':'Room for the life you choose.'}</h2><div class="life-metrics"><div><b>${cash(r.takeHome)}</b><span>take-home / month</span></div><div><b>${cash(r.spending)}</b><span>spending & cash savings</span></div><div><b>${cash(Math.abs(r.remaining))}</b><span>${deficit?'monthly shortfall':'left unallocated'}</span></div></div><div class="life-stack" role="img" aria-label="Monthly spending composition: ${cash(r.spending)}">${r.rows.map(([label,v],i)=>`<i title="${h(label)}: ${cash(v)}" style="width:${r.spending?v/r.spending*100:0}%;background:${['#627c67','#b2bfa5','#d9ba90','#bac5cb','#c3b3c7','#a5afa7'][i%6]}"></i>`).join('')}</div><p>${deficit?'The choices below are a wish list until this gap closes.':'Includes your savings goal. Irregular costs may use the remaining room.'}</p><button class="text-link" data-action="life-adjust" data-id="0">Adjust income →</button></section><div class="life-story-grid">${tile('⌂','HOME',p.housingMode==='own'?'Owning a home':Number(p.rent)<=1000?'Shared rental':'Renting alone',cash(r.housing)+' / month',p.housingMode==='own'?`<p>${cash(r.mortgage)} mortgage principal & interest. Includes tax, insurance, HOA, maintenance, and utilities.</p><p>${cash(r.upfront)} upfront target. ${cash(r.upfrontGap)} still to save.</p>${Number(p.downPercent)<20?`<p>PMI estimate included below 20% down: ${cash(r.pmi)} / month.</p>`:''}`:`<p>${cash(Number(p.rent))} rent + ${cash(Number(p.utilities))} utilities. Rent does not identify a specific home, size, or neighborhood.</p><p>${cash(r.rentBudget)} is the maximum rent that balances your other entered goals. It is not a market quote.</p>`,1)}${tile('↗','TRANSPORT',({transit:'Transit & occasional rides',paid:'A paid-off car',used:'A used compact car',new:'A new car'})[p.carMode],cash(r.transport)+' / month',`<p>${p.carMode==='transit'?'Transit and your extra ride budget.':`${cash(r.carPayment)} loan payment plus fuel, insurance, maintenance, and other costs.`}</p>${['used','new'].includes(p.carMode)?`<p>${cash(Number(p.carDown))} down payment is separate. Civic / Corolla are type examples.</p>`:''}`,2)}${tile('☕','DINING',(Math.round((Number(p.quickCount)+Number(p.casualCount)+Number(p.specialCount))*12/52*10)/10)+' dinners out / week',cash(r.dining)+' / month',`<p>${h(Math.round(Number(p.quickCount)*10)/10)} counter-service × ${cash(Number(p.quickPrice))}; ${h(Math.round(Number(p.casualCount)*10)/10)} sit-down × ${cash(Number(p.casualPrice))}; ${h(Math.round(Number(p.specialCount)*10)/10)} special × ${cash(Number(p.specialPrice))}. Per person, with tax and tip.</p><p>Price references: Kerbey Lane burger + iced tea ≈ $26 with 8.25% tax and 20% pretax tip; Uchi happy-hour tasting for two ≈ $77 each on the same basis. Drinks and extras vary. <a href="https://www.kerbeylanecafe.com/menu" target="_blank" rel="noopener noreferrer">Kerbey menu ↗</a> · <a href="https://uchi.uchirestaurants.com/location/sushi-austin/menu/" target="_blank" rel="noopener noreferrer">Uchi menu ↗</a>. Reviewed October 16, 2026.</p><p>Groceries are separate. These are chosen costs, not extra spending capacity.</p>`,4)}${tile('✈','TRAVEL',r.trips===null?'Set a trip budget':r.trips.toFixed(1)+' trip budgets / year',cash(Number(p.travel)*12)+' / year',`<p>${cash(Number(p.tripPrice))} per all-in trip. A fraction means saving longer. No specific itinerary or paid leave is assumed.</p>`,4)}${tile('✳','RECREATION',r.outings===null?'Set an outing budget':r.outings.toFixed(1)+' outings / month',cash(Number(p.recreation))+' / month',`<p>${cash(Number(p.outingPrice))} per outing. Mix free parks with shows, classes, sports, or memberships within this same fund.</p>`,4)}${tile('◇','PERSONAL STYLE',cash(Number(p.clothing)*12)+' clothing fund / year','Thrift · Target · Uniqlo',`<p>${r.items===null?'Choose a target price.':r.items.toFixed(1)+' items / year at '+cash(Number(p.itemPrice))+' each.'} Levi’s / Gap pieces or premium items mean fewer purchases or saving longer. Brand examples are not verified price quotes.</p>`,4)}</div>${more(`<table><caption>Monthly dollars · display rounded</caption><tbody>${r.taxes?`<tr><th>Gross pay</th><td>${cash(Number(p.gross)/12)}</td></tr><tr><th>Federal tax</th><td>−${cash(r.taxes.federal/12)}</td></tr><tr><th>Social Security & Medicare</th><td>−${cash((r.taxes.social+r.taxes.medicare)/12)}</td></tr><tr><th>Pretax retirement</th><td>−${cash(r.taxes.retirement/12)}</td></tr><tr><th>Health budget</th><td>−${cash(Number(p.health))}</td></tr>`:''}<tr><th>Take-home available</th><td>${cash(r.takeHome)}</td></tr>${r.rows.map(([label,v])=>`<tr><th>${h(label)}</th><td>${cash(v)}</td></tr>`).join('')}<tr><th>${deficit?'Shortfall':'Unallocated room'}</th><td>${cash(Math.abs(r.remaining))}</td></tr></tbody></table><p>Retirement and health have already been deducted. No employer benefits or contributions are assumed.</p>`,'Every dollar · full budget')}`;}

export function lifestyleOutput(p,{compact=false,example=false}={}){const story=lifestyleStory(p),range=lifestyleIncomeRange(p);if(story.key==='unknown')return lifestyleDetailOutput(p);return `<section class="lifestyle-picture picture-${story.key}"><span class="overline">${example?'AN AUSTIN EXAMPLE':'YOUR AUSTIN PICTURE'}</span><h2>${example?story.title.replace('your lifestyle','this example'):story.title}</h2><p>${example?story.copy.replaceAll('Your ','The ').replaceAll('your ','the '):story.copy}</p>${range?`<div class="picture-income-range"><span>${example?'Income needed for this example':'Income needed for your choices'}</span><strong>${formatSalary(range.low)}–${formatSalary(range.high)} / year</strong><p>Before tax. The lower end covers costs. The upper end adds a cushion.</p></div>`:''}${story.key==='tradeoffs'?'<p class="picture-tradeoff">'+(example?'Lower costs or higher pay would be needed.':'Lower your costs or choose a higher income.')+'</p>':''}</section>${compact?'<details class="more-info"><summary>More info · what this budget includes</summary>':''}<div class="life-story-grid abstract-stories">${story.tiles.map(t=>`<article class="life-story"><span class="life-symbol" aria-hidden="true">${storyGlyph(t.label)}</span><span class="overline">${t.label}</span><h3>${t.title}</h3><p>${t.copy}</p></article>`).join('')}</div>${compact?'</details>':''}${more(lifestyleDetailOutput(p),'More info · see the budget')}`;}
